#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Mfa {
    pub module: String,
    pub function: String,
    pub arity: u8,
}

impl fmt::Display for Mfa {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
