    if let Some(transfer) = process.take_jit_transfer() {
        return Ok(Some(match transfer {
            ExecutionResult::Waiting => InstructionOutcome::Waiting,
            ExecutionResult::DirtyCall {
                entry,
                args,
                module,
                function,
                arity,
                kind,
            } => InstructionOutcome::DirtyCall {
