                module,
                function,
                arity,
                kind,
            },
            // No helper parks these today — they still take the value and yield
            // returns in `jit_call_interpreted`. Mapped so the channel stays
            // total if one ever does.
            ExecutionResult::Exited(reason) => InstructionOutcome::Exit(reason),
            ExecutionResult::Yielded => InstructionOutcome::Yield,
        }));
    }
    match process.take_jit_status() {
        Some(JitStatus::Yield) => return Ok(Some(InstructionOutcome::Yield)),
        None => {}
    }
    match returned.status {
        JIT_STATUS_EXCEPTION => {
            // Compiled code propagated an exception out. It may still be
            // catchable HERE: a raise inside a nested run refuses handlers
            // installed outside its nesting (see `Process::nested_handler_floor`)
            // and leaves through this return precisely so the handler is found
            // at the depth that installed it, with the compiled frame already
            // appended to the trace. Re-offer it without recapturing; treating
            // this as an unconditional exit would make a caught exception kill
            // the process the moment its protected region crossed a trampoline.
            return match process.current_exception() {
                Some(exception) => {
                    super::exceptions::dispatch_captured_exception(process, exception).map(Some)
                }
                // The exception return is only produced with an exception on
                // the process; without one there is nothing to offer a handler.
                None => Ok(Some(InstructionOutcome::Exit(ExitReason::Error))),
            };
        }
        JIT_STATUS_DEOPT => return Ok(None),
        JIT_STATUS_YIELD => return Ok(Some(InstructionOutcome::Yield)),
        _ => {}
    }
    let raw = returned.value;
    if raw == JIT_YIELD_SENTINEL as u64 {
        return Ok(Some(InstructionOutcome::Yield));
    }
    if raw == JIT_DEOPT_SENTINEL as u64 {
        return Ok(None);
    }
    process.set_x_reg(0, Term::from_raw(raw));
    return_(process).map(Some)
}

fn push_y_frame(
    process: &mut Process,
    module: &Module,
    stack_need: &Operand,
) -> Result<InstructionOutcome, ExecError> {
    let slots = operand_u16(stack_need, "stack slots")?;
    let return_ip = process
        .code_position()
        .map_or(0, |position| position.instruction_pointer);
    let caller_module = current_module_pin(process, module);
    process
        .stack_mut()
        .push_frame(module.name, return_ip, caller_module, slots)
        .map_err(ExecError::from)?;
    Ok(InstructionOutcome::Continue)
}

pub(crate) fn deallocate_frame(process: &mut Process, words: &Operand) -> Result<(), ExecError> {
    let _words = operand_u16(words, "deallocate words")?;
    let _ = process.stack_mut().pop_frame().map_err(ExecError::from)?;
    Ok(())

