//! BEAMR-R8-DEOPT R3 / R3b — error IDENTITY across the deopt boundary, for the
//! four error-raising terminals `Badmatch`, `CaseEnd`, `IfEnd`, `Badrecord`.
//!
//! ACCEPTANCE IS IDENTITY, NOT "AN ERROR WAS RAISED". Each specimen's error edge
//! is forced and TAKEN, and the run is measured twice IN THIS ONE BINARY:
//! JIT'd-with-deopt, and never-JIT'd. What is compared is the whole caught
//! `{caught, Class, Reason, Stacktrace}` term rendered through the repo's own
//! `beamr::term::format::format_term` — class, reason term AND stacktrace, byte
//! for byte. An assertion that would still pass against a different reason term
//! is not an identity assertion.
//!
//! TAKEN-NESS IS ASSERTED, NOT INFERRED (three ways, all mechanical):
//!   1. the JIT arm asserts the specimen is IN THE JIT CACHE at the moment of
//!      the error drive, with the JIT enabled — and beamr's pre-pass admission
//!      is WHOLE-FUNCTION (`ir_control.rs` errs on the first non-Supported
//!      variant), so a cache entry for a function whose only cold edge is the
//!      terminal IS the proof that the terminal was lowered;
//!   2. the never-JIT'd arm asserts the cache is EMPTY for the same key;
//!   3. the happy input returns its value through that same cached native body
//!      in the same run (the R3b null arm), so the body is demonstrably entered.
//!
//! THE BADMATCH SPECIMEN IS A RESTART-FIDELITY FIXTURE. Both AWL construction
//! sites emit `Badmatch { value: Operand::X(0) }` verbatim (ablative-io/aion
//! `crates/aion-awl/src/mir/select/emit/burst.rs:293-295` and `:385-395`), so
//! NO lowering can report the walked tail by mis-reading the operand — the
//! operand is `X(0)` either way, and "the operand was X(0)" proves nothing.
//! What the fixture guards is that the deopt RESTARTS from the function's
//! bytecode entry rather than resuming mid-function on marshalled native
//! register state: the subject reaches `{x,0}` only because the restarted
//! interpreter re-executes the whole body. The specimen therefore uses a
//! subject whose walked tail at the point of failure is a NON-EMPTY PROPER
//! SUFFIX, and asserts both that the reason is `{badmatch, <whole subject>}`
//! and that it is NOT `{badmatch, <tail>}`.
//!
//! `Badrecord` is IDENTITY OF A NON-RAISE and is labelled as such: beamr's
//! interpreter has no `Badrecord` execution arm (`interpreter/opcodes/mod.rs`
//! dispatches Badmatch/CaseEnd/IfEnd only; `exceptions.rs` defines no
//! `badrecord`), so both arms yield the same `ExecError::UnsupportedOpcode`.
//! Identity holds; it is not evidence that the terminal raises correctly.
//!
//! Fixture provenance: `fixtures/awl_terminals.erl` is DERIVED from production
//! documents in our own public first-party repo `ablative-io/aion` —
//! `workflows/gates/gates.awl` and `workflows/investigate/investigate.awl`, the
//! census's own poisoned population. The header of that file records each
//! specimen's source line and what was cut.

use std::sync::Arc;
use std::sync::mpsc;
use std::time::{Duration, Instant};

use beamr::atom::{Atom, AtomTable};
use beamr::ets::OwnedTerm;
use beamr::loader::load_module;
use beamr::module::ModuleRegistry;
use beamr::native::BifRegistryImpl;
use beamr::process::ExitReason;
use beamr::scheduler::{NativeBifs, Scheduler, SchedulerConfig};
use beamr::term::Term;
use beamr::term::format::format_term;

const DEADLINE: Duration = Duration::from_secs(20);
const WAIT_BUDGET: Duration = Duration::from_secs(15);
/// Heat drives before the tier is asked for a verdict on the specimen.
const HEAT_DRIVES: usize = 8;

fn wait_until(mut predicate: impl FnMut() -> bool) -> bool {
    let deadline = Instant::now() + WAIT_BUDGET;
    while Instant::now() < deadline {
        if predicate() {
            return true;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    false
}

/// A scheduler over the `awl_terminals` fixture. `jit` false disables the JIT
/// IMMEDIATELY after construction and BEFORE any spawn, which the operator
/// switch's own contract states is what guarantees nothing is ever compiled AND
/// that already-compiled code is never entered — a large `jit_threshold` cannot
/// promise the second half.
fn start(atoms: &AtomTable, jit: bool) -> (Arc<Scheduler>, Arc<ModuleRegistry>) {
    let bifs = BifRegistryImpl::new();
    let registry = Arc::new(ModuleRegistry::new());
    load_module(
        include_bytes!("fixtures/awl_terminals.beam"),
        atoms,
        &registry,
        &bifs,
    )
    .expect("awl_terminals fixture loads");
    let scheduler = Arc::new(
        Scheduler::new(
            SchedulerConfig {
                thread_count: Some(1),
                dirty_cpu_threads: Some(1),
                dirty_io_threads: Some(1),
                jit_threshold: Some(2),
                ..SchedulerConfig::default()
            },
            Arc::clone(&registry),
            NativeBifs::registry(Arc::new(bifs)),
        )
        .expect("scheduler starts"),
    );
    if !jit {
        scheduler.set_jit_enabled(false);
    }
    (scheduler, registry)
}

/// Deadline-bound drive. A specimen that never terminates is a RED with its own
/// message, never a hang.
fn drive(scheduler: &Arc<Scheduler>, function: Atom, arg: Term) -> (ExitReason, OwnedTerm) {
    let module = module_atom();
    let pid = scheduler.spawn(module, function, vec![arg]).expect("spawn");
    let (tx, rx) = mpsc::channel();
    let sched = Arc::clone(scheduler);
    std::thread::spawn(move || {
        let _ = tx.send(sched.run_until_exit(pid));
    });
    rx.recv_timeout(DEADLINE)
        .unwrap_or_else(|_| panic!("drive did not terminate within {DEADLINE:?}"))
}

fn module_atom() -> Atom {
    AtomTable::with_common_atoms().intern("awl_terminals")
}

fn generation(registry: &Arc<ModuleRegistry>) -> u64 {
    registry
        .lookup(module_atom())
        .expect("fixture module is registered")
        .generation
}

fn specimen_cached(
    scheduler: &Arc<Scheduler>,
    registry: &Arc<ModuleRegistry>,
    specimen: Atom,
) -> bool {
    scheduler
        .jit_cache()
        .lookup(module_atom(), specimen, 1, generation(registry))
        .is_some()
}

/// One terminal's measurement in one composition.
struct Arm {
    /// Was the SPECIMEN (the function carrying the error terminal) admitted and
    /// cached native at the moment of the error drive?
    specimen_cached: bool,
    /// The R3b null arm: the happy path's rendered result.
    happy: String,
    /// The rendered `{caught, Class, Reason, Stacktrace}` from the taken edge.
    caught: String,
    /// Exit reason of the error drive (the catcher recovers, so `Normal` unless
    /// the raise escaped).
    error_exit: ExitReason,
    /// Host-level error, if the drive died instead of returning data. This is
    /// where `Badrecord`'s `UnsupportedOpcode` non-raise lands.
    error_host: Option<String>,
}

/// Heat the specimen, wait for a compile verdict, then measure the null (happy)
/// arm and the deopt (error) arm IN THAT ORDER, IN THE SAME RUN.
fn measure(
    atoms: &AtomTable,
    scheduler: &Arc<Scheduler>,
    registry: &Arc<ModuleRegistry>,
    specimen: Atom,
    probe: Atom,
    happy_entry: Atom,
    happy_arg: Term,
    error_arg: Term,
    expect_cached: bool,
) -> Arm {
    for _ in 0..HEAT_DRIVES {
        let (reason, _) = drive(scheduler, happy_entry, happy_arg);
        assert_eq!(
            reason,
            ExitReason::Normal,
            "heat drive of the happy path must exit normally"
        );
    }
    if expect_cached {
        assert!(
            wait_until(|| specimen_cached(scheduler, registry, specimen)),
            "the specimen carrying the error terminal must be ADMITTED and cached \
             native — this is the whole point of BEAMR-R8-DEOPT, and beamr's \
             pre-pass admission is whole-function, so a cache entry here IS the \
             proof the terminal was lowered rather than rejecting its container"
        );
    }
    let cached_now = specimen_cached(scheduler, registry, specimen);

    // R3b null arm: the HAPPY path, through that same body, in this same run.
    let (happy_reason, happy_value) = drive(scheduler, happy_entry, happy_arg);
    assert_eq!(
        happy_reason,
        ExitReason::Normal,
        "the cured function's happy path must still exit normally"
    );
    let happy = format_term(happy_value.root(), atoms);

    // R3 deopt arm: the error edge, TAKEN.
    let (error_exit, caught_value) = drive(scheduler, probe, error_arg);
    let error_host = scheduler.take_exit_error(0).map(|error| error.to_string());
    let caught = format_term(caught_value.root(), atoms);
    Arm {
        specimen_cached: cached_now,
        happy,
        caught,
        error_exit,
        error_host,
    }
}

/// The whole R3 + R3b measurement for one terminal, both compositions, one run.
struct Identity {
    native: Arm,
    interpreted: Arm,
}

fn identity_of(
    atoms: &AtomTable,
    specimen: &str,
    probe: &str,
    happy_entry: &str,
    happy_arg: impl Fn(&AtomTable) -> Term,
    error_arg: impl Fn(&AtomTable) -> Term,
) -> Identity {
    let specimen_atom = atoms.intern(specimen);
    let probe_atom = atoms.intern(probe);
    let happy_atom = atoms.intern(happy_entry);

    let (jit, jit_registry) = start(atoms, true);
    let native = measure(
        atoms,
        &jit,
        &jit_registry,
        specimen_atom,
        probe_atom,
        happy_atom,
        happy_arg(atoms),
        error_arg(atoms),
        true,
    );
    jit.shutdown();

    let (plain, plain_registry) = start(atoms, false);
    let interpreted = measure(
        atoms,
        &plain,
        &plain_registry,
        specimen_atom,
        probe_atom,
        happy_atom,
        happy_arg(atoms),
        error_arg(atoms),
        false,
    );
    assert!(
        !interpreted.specimen_cached,
        "the never-JIT'd arm must have NO cached native body for the specimen"
    );
    plain.shutdown();

    Identity {
        native,
        interpreted,
    }
}

/// The identity assertion itself, plus the transcript the flight report carries.
fn assert_identity(label: &str, identity: &Identity) {
    let native = &identity.native;
    let interpreted = &identity.interpreted;
    println!("---- BEAMR-R8-DEOPT R3 transcript: {label} ----");
    println!("  native-with-deopt : specimen cached = {}", native.specimen_cached);
    println!("  never-JIT'd       : specimen cached = {}", interpreted.specimen_cached);
    println!("  R3b null arm (happy path, same run)");
    println!("    native      : {}", native.happy);
    println!("    interpreted : {}", interpreted.happy);
    println!("  R3 deopt arm (error edge TAKEN)");
    println!("    native      : exit={:?} caught={} host_error={:?}",
        native.error_exit, native.caught, native.error_host);
    println!("    interpreted : exit={:?} caught={} host_error={:?}",
        interpreted.error_exit, interpreted.caught, interpreted.error_host);

    assert!(
        native.specimen_cached,
        "{label}: the specimen must be cached native for the edge to be taken in native code"
    );
    assert_eq!(
        native.happy, interpreted.happy,
        "{label}: R3b — the cure must not perturb the path that never traps; the \
         happy path must be byte-identical JIT'd vs interpreted"
    );
    assert_eq!(
        native.caught, interpreted.caught,
        "{label}: R3 — ERROR IDENTITY. class, reason term and stacktrace must be \
         byte-identical between the native-with-deopt run and the never-JIT'd run"
    );
    assert_eq!(
        (native.error_exit, native.error_host.as_deref()),
        (interpreted.error_exit, interpreted.error_host.as_deref()),
        "{label}: the error drive's exit reason and host error must also match"
    );
}

fn list_of(atoms: &AtomTable, names: &[&str]) -> Term {
    // Built on the caller's side as a literal list through the fixture's own
    // entry is not possible (spawn takes ready terms), so the list is built as
    // an immediate: beamr's `Term::NIL` + cons cells need a heap, and the
    // scheduler owns process heaps — so the specimens that need a list take an
    // ATOM SELECTOR instead and build the list in bytecode. See `list_selector`.
    let _ = (atoms, names);
    unreachable!("lists are built in bytecode; see list_selector")
}

fn list_selector(atoms: &AtomTable, name: &str) -> Term {
    Term::atom(atoms.intern(name))
}

#[test]
fn case_end_error_identity_across_the_deopt_boundary() {
    let atoms = AtomTable::with_common_atoms();
    let identity = identity_of(
        &atoms,
        "verdict_code",
        "probe_verdict",
        "happy_verdict",
        |a| Term::atom(a.intern("already_fixed")),
        |a| Term::atom(a.intern("no_such_verdict")),
    );
    assert_identity("CaseEnd — {case_clause, V}", &identity);
    assert!(
        identity.native.caught.contains("case_clause")
            && identity.native.caught.contains("no_such_verdict"),
        "CaseEnd's reason must be {{case_clause, <the unmatched value>}}, got: {}",
        identity.native.caught
    );
    let _ = list_selector(&atoms, "unused");
}

#[test]
fn if_end_error_identity_across_the_deopt_boundary() {
    let atoms = AtomTable::with_common_atoms();
    let identity = identity_of(
        &atoms,
        "report_presence",
        "probe_presence",
        "happy_presence",
        |a| Term::atom(a.intern("report")),
        |a| Term::atom(a.intern("absent")),
    );
    assert_identity("IfEnd — the BARE atom if_clause", &identity);
    assert!(
        identity.native.caught.contains("if_clause"),
        "IfEnd's reason must be if_clause, got: {}",
        identity.native.caught
    );
    assert!(
        !identity.native.caught.contains("{if_clause"),
        "IfEnd's reason must be the BARE ATOM `if_clause`, never a tuple-wrapped \
         {{if_clause, []}} — a tuple reason does not match `catch error:if_clause` \
         in loaded bytecode (interpreter/opcodes/exceptions.rs carries the prior \
         regression in its own comment). Got: {}",
        identity.native.caught
    );
}

#[test]
fn badrecord_identity_of_a_non_raise_across_the_deopt_boundary() {
    let atoms = AtomTable::with_common_atoms();
    let identity = identity_of(
        &atoms,
        "gate_passed",
        "probe_gate_passed",
        "happy_gate_passed",
        |a| Term::atom(a.intern("gate_result_placeholder")),
        |a| Term::atom(a.intern("not_a_gate_result")),
    );
    assert_identity("Badrecord — IDENTITY OF A NON-RAISE", &identity);
}
