    match code {
        8 => out.push_str("\\b"),
        9 => out.push_str("\\t"),
        10 => out.push_str("\\n"),
        11 => out.push_str("\\v"),
        12 => out.push_str("\\f"),
        13 => out.push_str("\\r"),
        27 => out.push_str("\\e"),
        34 => out.push_str("\\\""),
        92 => out.push_str("\\\\"),
        32..=126 | 160..=255 => out.push(char::from_u32(code)?),
        _ => return None,

